contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(dummy == 0 || dummy != 0);
        uint balBefore = address(c).balance;
        uint ownerBefore = address(this).balance;
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint balAfter = address(c).balance;
        uint ownerAfter = address(this).balance;
        assert(reverted
            ? (balAfter == balBefore && ownerAfter == ownerBefore)
            : (balAfter == 0 && ownerAfter == ownerBefore + balBefore));
    }

    receive() external payable {}
}

