// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 dummy) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(dummy == 0 || dummy != 0);
        uint balBefore = address(c).balance;
        uint ownerBefore = address(this).balance;
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        uint balAfter = address(c).balance;
        uint ownerAfter = address(this).balance;
        assertTrue(reverted
            ? (balAfter == balBefore && ownerAfter == ownerBefore)
            : (balAfter == 0 && ownerAfter == ownerBefore + balBefore));
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
